import z3

# Graph G_{3,8}
n_cliques = 8
n_vertices_per = 3
total_vertices = n_cliques * n_vertices_per  # 24
total_edges = 45

# Create variables
vars = {}
for g in range(n_cliques):
    for i in range(n_vertices_per):
        vars[(g,i)] = z3.Int(f"v_{g}_{i}")

solver = z3.Solver()

# Domain: each label in [0,45]
for v in vars.values():
    solver.add(v >= 0)
    solver.add(v <= 45)

# All distinct
solver.add(z3.Distinct(list(vars.values())))

# Edge labels
edge_labels = []
# Within cliques
for g in range(n_cliques):
    for i in range(n_vertices_per):
        for j in range(i+1, n_vertices_per):
            a = vars[(g,i)]
            b = vars[(g,j)]
            edge_labels.append(z3.Abs(a - b))
# Between consecutive cliques
for g in range(n_cliques - 1):
    for i in range(n_vertices_per):
        a = vars[(g,i)]
        b = vars[(g+1,i)]
        edge_labels.append(z3.Abs(a - b))

# All edge labels distinct and in 1..45
solver.add(z3.Distinct(edge_labels))
for el in edge_labels:
    solver.add(el >= 1)
    solver.add(el <= 45)

# Check satisfiability
result = solver.check()
print(result)
if result == z3.sat:
    model = solver.model()
    solution = []
    for g in range(n_cliques):
        for i in range(n_vertices_per):
            solution.append(model[vars[(g,i)]].as_long())
    print(solution)
else:
    print("UNSAT")

# Let's try using PySAT with a direct encoding
from pysat import formula, solvers
import itertools

n_cliques = 8
n_vertices_per = 3
total_vertices = 24
total_edges = 45
max_label = 45

# Build edges
edges = []
# Within cliques
for g in range(n_cliques):
    for i in range(n_vertices_per):
        for j in range(i+1, n_vertices_per):
            edges.append((g*3+i, g*3+j))
# Between consecutive cliques
for g in range(n_cliques - 1):
    for i in range(n_vertices_per):
        edges.append((g*3+i, (g+1)*3+i))

print(f"Total edges: {len(edges)}")

# Let's try a different approach: use a SAT solver with a more compact encoding
# We'll use the "direct encoding" where for each vertex v and label l, 
# we have a boolean variable x_{v,l} meaning vertex v gets label l.
# For each edge e and label d, we have y_{e,d} meaning edge e has label d.

# Number of variables: 24*46 + 45*45 = 1104 + 2025 = 3129
# That's manageable.

# Let me try this encoding
from pysat import formula as f

# Create a SAT formula
sat = f.CNF()

# Variables: 
# For vertex v (0..23) and label l (0..45): var = v*46 + l + 1 (1-indexed)
# For edge e (0..44) and label d (1..45): var = 24*46 + e*45 + d + 1

def vertex_var(v, l):
    return v * 46 + l + 1

def edge_var(e, d):
    return 24 * 46 + e * 45 + d + 1

total_vars = 24 * 46 + 45 * 45
print(f"Total variables: {total_vars}")

# Each vertex gets exactly one label
for v in range(total_vertices):
    # At least one label
    sat.add_clause([vertex_var(v, l) for l in range(max_label + 1)])
    # At most one label (pairwise)
    for l1 in range(max_label + 1):
        for l2 in range(l1 + 1, max_label + 1):
            sat.add_clause([-vertex_var(v, l1), -vertex_var(v, l2)])

# Each label is used at most once (since we have 24 vertices and 46 labels, some labels are unused)
for l in range(max_label + 1):
    for v1 in range(total_vertices):
        for v2 in range(v1 + 1, total_vertices):
            sat.add_clause([-vertex_var(v1, l), -vertex_var(v2, l)])

# Each edge gets exactly one label
for e in range(total_edges):
    sat.add_clause([edge_var(e, d) for d in range(1, max_label + 1)])
    for d1 in range(1, max_label + 1):
        for d2 in range(d1 + 1, max_label + 1):
            sat.add_clause([-edge_var(e, d1), -edge_var(e, d2)])

# Each edge label is used at most once
for d in range(1, max_label + 1):
    for e1 in range(total_edges):
        for e2 in range(e1 + 1, total_edges):
            sat.add_clause([-edge_var(e1, d), -edge_var(e2, d)])

# Edge label consistency: if edge e connects vertices u and v, and edge e has label d,
# then |label(u) - label(v)| = d
# This means: for each edge e = (u,v), for each pair of labels (l1, l2) such that |l1-l2| = d,
# we need: if vertex u has label l1 and vertex v has label l2, then edge e has label d
# Equivalently: not (vertex u has l1 and vertex v has l2 and edge e does NOT have d)
# Or: -vertex_var(u,l1) OR -vertex_var(v,l2) OR edge_var(e,d)

for e, (u, v) in enumerate(edges):
    for l1 in range(max_label + 1):
        for l2 in range(max_label + 1):
            d = abs(l1 - l2)
            if d >= 1 and d <= max_label:
                sat.add_clause([-vertex_var(u, l1), -vertex_var(v, l2), edge_var(e, d)])

print(f"Total clauses: {len(sat.clauses)}")

# Try to solve
solver_obj = solvers.Glucose3(sat)
result = solver_obj.solve()
print(f"Result: {result}")
if result:
    model = solver_obj.get_model()
    # Extract vertex labels
    solution = []
    for v in range(total_vertices):
        for l in range(max_label + 1):
            if model[vertex_var(v, l) - 1] > 0:
                solution.append(l)
                break
    print(solution)
